arguments.command:
generation_output=$(curl --request POST --url https://cloud.leonardo.ai/api/rest/v1/generations --header 'accept: application/json' --header 'authorization: Bearer dddd08ff-d8c3-4fec-98d9-9e8c060f4619' --header 'content-type: application/json' --data '{"prompt": "professional editorial illustration of Bitcoin cryptocurrency bull market, institutional investors, golden bitcoin coins, modern financial district skyline, cinematic blue and gold lighting, digital art", "modelId": "7b592283-e8a7-4c5a-9ba6-d18c31f258b9", "num_images": 1, "width": 1024, "height": 576}');
generation_id=$(echo $generation_output | sed -n 's/.*"generationId":"\([^"]*\)".*/\1/p');
sleep 10 &&
poll_output=$(curl --request GET --url "https://cloud.leonardo.ai/api/rest/v1/generations/$generation_id" --header 'authorization: Bearer dddd08ff-d8c3-4fec-98d9-9e8c060f4619') &&
image_url=$(echo $poll_output | sed -n 's/.*"url":"\([^"]*\)".*/\1/p') &&
curl -o /tmp/crypto-feature.jpg "$image_url"
